# ElastiCache Redis cluster (2 nodes, Multi-AZ)
aws elasticache create-replication-group \
  --replication-group-id my-app-redis \
  --replication-group-description "Session and cache store" \
  --num-cache-clusters 2 \
  --cache-node-type cache.t3.medium \
  --engine redis \
  --engine-version 7.0 \
  --automatic-failover-enabled \
  --multi-az-enabled \
  --cache-subnet-group-name my-private-subnet-group \
  --security-group-ids sg-redis-id

# pom.xml — Spring Session Redis dependency
<dependency>
  <groupId>org.springframework.boot</groupId>
  <artifactId>spring-boot-starter-data-redis</artifactId>
</dependency>
<dependency>
  <groupId>org.springframework.session</groupId>
  <artifactId>spring-session-data-redis</artifactId>
</dependency>

# application-prod.yml
spring:
  session:
    store-type: redis          # switch from in-memory to Redis
    timeout: 30m               # session TTL
  data:
    redis:
      host: ${REDIS_HOST}      # ElastiCache primary endpoint
      port: 6379
      ssl:
        enabled: true          # in-transit encryption

# Caching lookup data with TTL (Spring @Cacheable + Redis)
@Configuration
@EnableCaching
public class CacheConfig {
    @Bean
    public RedisCacheConfiguration cacheConfig() {
        return RedisCacheConfiguration.defaultCacheConfig()
            .entryTtl(Duration.ofMinutes(10))   // auto-expire stale data
            .disableCachingNullValues();
    }
}

// Any bean method — cache result in Redis automatically
@Cacheable(value = "products", key = "#id")
public Product getProduct(Long id) {
    return productRepository.findById(id).orElseThrow();
}

// Evict on update
@CacheEvict(value = "products", key = "#product.id")
public Product updateProduct(Product product) {
    return productRepository.save(product);
}

// Jenkinsfile (declarative)
pipeline {
  agent any

  environment {
    AWS_REGION       = 'ap-southeast-1'
    ECR_REGISTRY     = '123456789.dkr.ecr.ap-southeast-1.amazonaws.com'
    IMAGE_NAME       = 'my-app'
    ECS_CLUSTER      = 'my-app-cluster'
    ECS_SERVICE      = 'my-app-service'
    TASK_FAMILY      = 'my-app'
  }

  stages {
    stage('Checkout') {
      steps { checkout scm }
    }

    stage('Unit Tests') {
      steps {
        sh 'mvn test'
      }
      post {
        always { junit 'target/surefire-reports/*.xml' }
      }
    }

    stage('Build Image') {
      steps {
        script {
          env.IMAGE_TAG = sh(script: 'git rev-parse --short HEAD', returnStdout: true).trim()
          sh "docker build -t ${ECR_REGISTRY}/${IMAGE_NAME}:${IMAGE_TAG} ."
        }
      }
    }

    stage('Push to ECR') {
      steps {
        withAWS(region: AWS_REGION, credentials: 'aws-jenkins') {
          sh "aws ecr get-login-password | docker login --username AWS --password-stdin ${ECR_REGISTRY}"
          sh "docker push ${ECR_REGISTRY}/${IMAGE_NAME}:${IMAGE_TAG}"
        }
      }
    }

    stage('Register New Task Definition') {
      steps {
        withAWS(region: AWS_REGION, credentials: 'aws-jenkins') {
          sh """
            TASK_DEF=\$(aws ecs describe-task-definition --task-definition ${TASK_FAMILY})
            NEW_TASK=\$(echo \$TASK_DEF | jq --arg IMG "${ECR_REGISTRY}/${IMAGE_NAME}:${IMAGE_TAG}" \
              '.taskDefinition | .containerDefinitions[0].image = \$IMG | \
               del(.taskDefinitionArn,.revision,.status,.requiresAttributes,.compatibilities,.registeredAt,.registeredBy)')
            aws ecs register-task-definition --cli-input-json "\$NEW_TASK"
          """
        }
      }
    }

    stage('Deploy') {
      steps {
        withAWS(region: AWS_REGION, credentials: 'aws-jenkins') {
          sh """
            aws ecs update-service \
              --cluster ${ECS_CLUSTER} \
              --service ${ECS_SERVICE} \
              --task-definition ${TASK_FAMILY} \
              --deployment-configuration 'maximumPercent=200,minimumHealthyPercent=100' \
              --force-new-deployment
          """
        }
      }
    }
  }

  post {
    failure { slackSend channel: '#alerts', message: "FAILED: ${env.JOB_NAME} ${env.BUILD_NUMBER}" }
    success { slackSend channel: '#deploys', message: "DEPLOYED: ${env.JOB_NAME} ${env.IMAGE_TAG}" }
  }
}
